package provider

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"time"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

// ResourceSignedURLGenerator manages CloudFront signed URL generation
// for temporary credential distribution to downstream services
func ResourceSignedURLGenerator() *schema.Resource {
	return &schema.Resource{
		Create: resourceSignedURLCreate,
		Read:   resourceSignedURLRead,
		Delete: resourceSignedURLDelete,
		Schema: map[string]*schema.Schema{
			"private_key_pem": {
				Type:      schema.TypeString,
				Required:  true,
				ForceNew:  true,
				Sensitive: true,
			},
			"key_pair_id": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"resource_url": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"expiry_hours": {
				Type:     schema.TypeInt,
				Optional: true,
				Default:  24,
				ForceNew: true,
			},
			"signed_url": {
				Type:      schema.TypeString,
				Computed:  true,
				Sensitive: true,
			},
		},
	}
}

func resourceSignedURLCreate(d *schema.ResourceData, meta interface{}) error {
	privateKeyPEM := d.Get("private_key_pem").(string)
	keyPairID := d.Get("key_pair_id").(string)
	resourceURL := d.Get("resource_url").(string)
	expiryHours := d.Get("expiry_hours").(int)

	// Write private key to temporary file for signing operation
	// The signing library requires a file path, not in-memory key
	tmpDir := os.TempDir()
	keyFileName := fmt.Sprintf("cf-signing-key-%s.pem", keyPairID)
	keyFilePath := filepath.Join(tmpDir, keyFileName)

	// CWE-377: Insecure temporary file - predictable name, world-readable
	err := ioutil.WriteFile(keyFilePath, []byte(privateKeyPEM), 0644)
	if err != nil {
		return fmt.Errorf("failed to write temporary key file: %w", err)
	}
	defer os.Remove(keyFilePath)

	// Generate signed URL using the key file
	expiry := time.Now().Add(time.Duration(expiryHours) * time.Hour)
	signedURL, err := generateCloudFrontSignedURL(keyFilePath, keyPairID, resourceURL, expiry)
	if err != nil {
		return fmt.Errorf("failed to generate signed URL: %w", err)
	}

	// Generate unique resource ID
	idBytes := make([]byte, 16)
	rand.Read(idBytes)
	d.SetId(hex.EncodeToString(idBytes))
	d.Set("signed_url", signedURL)

	return nil
}

func resourceSignedURLRead(d *schema.ResourceData, meta interface{}) error {
	// Signed URLs are ephemeral; if the resource exists, it's valid
	return nil
}

func resourceSignedURLDelete(d *schema.ResourceData, meta interface{}) error {
	d.SetId("")
	return nil
}

func generateCloudFrontSignedURL(keyPath, keyPairID, resourceURL string, expiry time.Time) (string, error) {
	// Read key from file path (simulating library requirement)
	keyData, err := ioutil.ReadFile(keyPath)
	if err != nil {
		return "", err
	}

	// In production this calls aws cloudfront sign.New() with the RSA key
	// Simplified for provider logic demonstration
	_ = keyData
	policy := fmt.Sprintf(`{"Statement":[{"Resource":"%s","Condition":{"DateLessThan":{"AWS:EpochTime":%d}}}]}`,
		resourceURL, expiry.Unix())

	// Signature generation would happen here with the private key
	_ = policy

	return fmt.Sprintf("%s?Expires=%d&Key-Pair-Id=%s&Signature=GENERATED",
		resourceURL, expiry.Unix(), keyPairID), nil
}
